var i=194;var n=[{id:`cooking-194-01`,theoryId:194,type:`single_choice`,difficulty:`beginner`,safetyCritical:!1,question:{en:`What does creaming butter and sugar usually accomplish?`,ua:`Яка типова мета збивання масла з цукром?`},explanation:{en:`Creaming can create small air cells that contribute to cake texture.`,ua:`Збивання створює дрібні повітряні комірки, які впливають на текстуру кексу.`},options:[{id:`a`,text:{en:`Dissolve all flour into oil`,ua:`Розчинити все борошно в олії`}},{id:`b`,text:{en:`Cook the eggs before adding them`,ua:`Зварити яйця перед додаванням`}},{id:`c`,text:{en:`Trap air and create a lightened mixture`,ua:`Утримати повітря й зробити суміш легшою`}}],answer:{optionIds:[`c`]}},{id:`cooking-194-02`,theoryId:194,type:`true_false`,difficulty:`beginner`,safetyCritical:!1,question:{en:`The muffin method generally mixes wet and dry components separately before combining them gently.`,ua:`Метод мафінів зазвичай передбачає окреме змішування сухих і рідких складників та делікатне об’єднання.`},explanation:{en:`Gentle mixing reduces excessive gluten development in tender batters.`,ua:`Делікатне змішування обмежує надмірний розвиток клейковини в ніжному тісті.`},answer:{value:!0}},{id:`cooking-194-03`,theoryId:194,type:`matching`,difficulty:`intermediate`,safetyCritical:!1,question:{en:`Match mixing methods with characteristic actions.`,ua:`Поєднайте методи змішування з характерними діями.`},explanation:{en:`Mixing order and intensity shape crumb texture.`,ua:`Послідовність та інтенсивність змішування формують структуру м’якушки.`},leftItems:[{id:`l1`,text:{en:`Creaming`,ua:`Збивання масла з цукром`}},{id:`l2`,text:{en:`Muffin method`,ua:`Метод мафінів`}},{id:`l3`,text:{en:`Foam method`,ua:`Пінний метод`}}],rightItems:[{id:`r2`,text:{en:`Combine separate wet and dry mixes gently`,ua:`Обережно з’єднати окремі суху й рідку суміші`}},{id:`r3`,text:{en:`Whip eggs or whites to incorporate air`,ua:`Збити яйця чи білки для насичення повітрям`}},{id:`r1`,text:{en:`Aerate plastic butter with sugar`,ua:`Наситити повітрям пластичне масло з цукром`}}],answer:{pairs:[{leftId:`l1`,rightId:`r1`},{leftId:`l2`,rightId:`r2`},{leftId:`l3`,rightId:`r3`}]}},{id:`cooking-194-04`,theoryId:194,type:`decision_scenario`,difficulty:`intermediate`,safetyCritical:!1,question:{en:`Muffins repeatedly bake with tough, tunnelled interiors. What is a likely adjustment?`,ua:`Мафіни постійно виходять твердими, з великими тунелями всередині. Що змінити?`},explanation:{en:`Overmixing can promote gluten development and tunneling.`,ua:`Надмірне перемішування може розвивати клейковину й спричиняти тунелі.`},options:[{id:`a`,text:{en:`Mix less after wet and dry ingredients come together`,ua:`Менше перемішувати після з’єднання сухих і рідких складників`}},{id:`b`,text:{en:`Beat for ten extra minutes`,ua:`Збивати ще десять хвилин`}},{id:`c`,text:{en:`Add dry flour until batter becomes a solid ball`,ua:`Додавати борошно, доки тісто не стане твердою кулею`}}],answer:{optionIds:[`a`]}},{id:`cooking-194-05`,theoryId:194,type:`multiple_choice`,difficulty:`intermediate`,safetyCritical:!1,question:{en:`Which practices support consistent cake mixing?`,ua:`Які дії допомагають стабільно змішувати тісто для кексів?`},explanation:{en:`Ingredient function and mixing method must be considered together.`,ua:`Потрібно враховувати одночасно функції інгредієнтів і метод змішування.`},options:[{id:`a`,text:{en:`Follow the intended ingredient temperatures`,ua:`Дотримуватися потрібних температур інгредієнтів`}},{id:`b`,text:{en:`Use the method specified for the batter`,ua:`Використовувати відповідний метод змішування`}},{id:`c`,text:{en:`Assume every batter requires maximum mixing`,ua:`Вважати, що кожне тісто потребує максимальної інтенсивності`}},{id:`d`,text:{en:`Measure ingredients accurately`,ua:`Точно відмірювати складники`}}],answer:{optionIds:[`a`,`b`,`d`]}}];var a={theoryId:194,exercises:n};export{a as default,n as exercises,i as theoryId};